import{_ as s,C as n,o,c as r,a2 as a,E as i}from"./chunks/framework.BAQ5ZYJQ.js";const y=JSON.parse('{"title":"The screen","description":"","frontmatter":{},"headers":[],"relativePath":"guide/tui.md","filePath":"guide/tui.md","lastUpdated":1792187838000}'),d={name:"guide/tui.md"};function h(c,e,p,l,u,g){const t=n("Term");return o(),r("div",null,[e[0]||(e[0]=a('<h1 id="the-screen" tabindex="-1">The screen <a class="header-anchor" href="#the-screen" aria-label="Permalink to &quot;The screen&quot;">​</a></h1><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tui</span></span></code></pre></div><p>Here it is, over three places at once — your machine, a container, and a cluster behind ssh and Slurm. Search a case, press enter, tick the places, and each one gets its own row:</p>',3)),i(t,{scene:"tui",caption:"errand tui, drawn by hand from the screens below: a case ticked on three environments, each with its own stack of layers. The rows fill in as the runs finish; the cluster's output shows the ssh, the allocation and the fetch back."}),e[1]||(e[1]=a(`<p><strong>Two pages</strong>, because there are two questions: <em>what do I run</em>, and <em>what came of it</em>.</p><p>No focus to keep track of: one rectangle is active, the arrows drive it, and clicking one selects it; the wheel scrolls whatever is under the pointer and changes nothing else.</p><p><strong><code>tab</code> walks the rectangles of the page; the function keys are the verbs.</strong> What you type is the search, on either page — so the letters are spoken for, and a verb belongs on a key nothing else can claim. <code>F2</code> and <code>F3</code> are the page before and the page after: two pages, two keys side by side, nothing to aim at, only a direction.</p><table tabindex="0"><thead><tr><th></th><th></th><th></th><th></th></tr></thead><tbody><tr><td><code>F1</code></td><td>these keys</td><td><code>F5</code> <code>F6</code></td><td>run the last command again · the one under the cursor</td></tr><tr><td><code>F2</code> <code>F3</code></td><td>the page before · after</td><td><code>F7</code> <code>F8</code></td><td>interrupt what is running · open the file</td></tr><tr><td><code>tab</code></td><td>the next rectangle</td><td><code>F9</code></td><td>read the project again</td></tr><tr><td><code>esc</code></td><td>clear the search, then leave</td><td><code>F12</code></td><td>leave</td></tr></tbody></table><p>The screen has nothing of its own: it writes a command, and it reads <a href="./output">the record of every run</a> — <code>.errand/runs/</code>, and <code>runs/</code> where <code>-o</code> made one. Everything it shows you could have got with <code>errand</code> and <code>ls</code>.</p><h2 id="cases-—-what-do-i-run" tabindex="-1">cases — what do I run <a class="header-anchor" href="#cases-—-what-do-i-run" aria-label="Permalink to &quot;cases — what do I run&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> [cases]   runs                                      errand · myproject · idle</span></span>
<span class="line"><span> find: shp gpu_</span></span>
<span class="line"><span> ╭─ cases  3 found ──────────────────────╮╭─ solve ─────────────────────────────╮</span></span>
<span class="line"><span> │   solve            bench/shapes.py:42 ││ bench/shapes.py:42                  │</span></span>
<span class="line"><span> │   solve_coarse     bench/shapes.py:61 ││ kind: bench                         │</span></span>
<span class="line"><span> │   shape_gradient   tests/geometry.py:9││ tags: gpu, slow                     │</span></span>
<span class="line"><span> ╰───────────────────────────────────────╯│ needs: gpus=1                       │</span></span>
<span class="line"><span>                                          │                                     │</span></span>
<span class="line"><span>                                          │ --n   default 1000                  │</span></span>
<span class="line"><span>                                          │   how many points                   │</span></span>
<span class="line"><span>                                          │                                     │</span></span>
<span class="line"><span>                                          │ last run                            │</span></span>
<span class="line"><span>                                          │   PASS   gpu   gpu@gpu-box          │</span></span>
<span class="line"><span>                                          │   12.4s                             │</span></span>
<span class="line"><span>                                          │   seconds = 12.406                  │</span></span>
<span class="line"><span>                                          ╰─────────────────────────────────────╯</span></span>
<span class="line"><span> type to search · enter runs it · space ticks · tab next box · F3 runs · F1 keys</span></span></code></pre></div><p><strong>Typing is the search</strong> — there is no key to press first, because finding one case among three hundred is what this page is for.</p><p>It is the matching an editor&#39;s <em>go to file</em> does, not an edit distance: the letters have to appear <strong>in order but not together</strong>, so <code>tsq</code> finds <code>tests/test_shapes.py::quick</code>. Then they are <em>scored</em> — together beats scattered, the start of a word beats the middle of one, early beats late, short beats long — and the letters that matched are shown in bold, so a row tells you why it is there.</p><p>Several words all have to be found, each possibly in a different place: <code>shp gpu</code> is &quot;a case whose name looks like shp <strong>and</strong> whose tags or file say gpu&quot;. Adding a word narrows; you never have to rewrite what you typed.</p><p><strong><code>esc</code> clears what you typed</strong>, and only then leaves: a filter is the thing you most want gone, and it should not be the hardest to get rid of. While a search is on, space is a word separator, so the tick is <code>ctrl-space</code> — or a click straight on the box.</p><p>With nothing typed, the cases are <strong>a tree of directories and files</strong>, because that is the shape the work has: a project is a layout before it is a list, and the directory is how you remember where a case lives. A directory holding one single thing does not cost a row of its own — its name joins its child&#39;s, <code>bench/gpu/heavy.py</code> on one line, since a row you can only walk through tells you nothing.</p><p>Facing them: everything about the one under the cursor, down to how it went the last time it ran — read out of <a href="./output">the output tree</a>, so it is there after a restart and after somebody else ran it.</p><p>A file that declares work and will not import costs its own row, marked <code>!</code>, with the traceback facing it. Half a project installed is an ordinary state of affairs; an empty screen is a poor way of saying so.</p><h2 id="runs-—-what-came-of-it" tabindex="-1">runs — what came of it <a class="header-anchor" href="#runs-—-what-came-of-it" aria-label="Permalink to &quot;runs — what came of it&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> cases   [runs]                                   errand · myproject · running</span></span>
<span class="line"><span> find: a command</span></span>
<span class="line"><span> ╭─ runs ────────────────────────────────╮╭─ files ─────────────────────────────╮</span></span>
<span class="line"><span> │ ▾ errand shapes --n 1e3,5e3       4/8 ││   shape.svg                 12.1 kB │</span></span>
<span class="line"><span> │   ok    solve  n=1000  [local]        ││   result.yaml                 512 B │</span></span>
<span class="line"><span> │   ok    solve  n=1000  [gpu]          ││   output.txt                 1.2 kB │</span></span>
<span class="line"><span> │   ..    solve  n=5000  [local]        │╰─────────────────────────────────────╯</span></span>
<span class="line"><span> │ ▸ errand run -k bench --fp 32   6 ok  │╭─ output.txt ────────────────────────╮</span></span>
<span class="line"><span> │ ▸ errand tests --n 10           1 ok  ││ iteration 41   residual 3.1e-07     │</span></span>
<span class="line"><span> ╰───────────────────────────────────────╯│ iteration 42   residual 1.9e-07     │</span></span>
<span class="line"><span>                                          ╰─────────────────────────────────────╯</span></span></code></pre></div><p><strong>Runs and history are one list</strong>, because they are one thing: a command, and what it produced. Today&#39;s is at the top and still moving, yesterday&#39;s is three rows down, and both read the same way — both are read out of the record rather than remembered.</p><p>Fold one open to see its cases; <code>F6</code> runs it again, and <code>F5</code> runs the last one again from either page. <strong>The runs page is searched the same way</strong>, over the commands: a history is only useful once one line of it can be found. The two searches are separate, so the one you keep on <code>cases</code> is still there when you come back from looking at <code>runs</code>.</p><p>Facing them: the files a run wrote, and below, the one under the cursor. Text is shown as text — <code>output.txt</code> follows the run as it is written — and anything else says what it is and how big. Enter or <code>F8</code> hands it to the desktop (<code>xdg-open</code>, <code>open</code>), so an experiment&#39;s <code>.svg</code> is two keys from the case that produced it.</p><h2 id="asking-where" tabindex="-1">asking where <a class="header-anchor" href="#asking-where" aria-label="Permalink to &quot;asking where&quot;">​</a></h2><p>Enter on a case asks the only question left: where, with which tags, with which parameters — not <em>which case</em>, which was the list you pressed enter in.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> ╭─ run: solve ──────────────────────────────────────────────────────────────────╮</span></span>
<span class="line"><span> │ › --env    [x] local   [x] gpu                      two ticks is two runs     │</span></span>
<span class="line"><span> │   --fp     [x] 32      [x] 64                    only the ones that say so    │</span></span>
<span class="line"><span> │   --n      1000,5000                                     how many points      │</span></span>
<span class="line"><span> │   -j       1                                             how many at once     │</span></span>
<span class="line"><span> │   --batch  [ ] detach                                 outlives this window    │</span></span>
<span class="line"><span> │   ─────────────────────────────────────────────────────────────────────────   │</span></span>
<span class="line"><span> │   errand run --env local,gpu --fp 32,64 bench/shapes.py::solve --n 1000,5000        │</span></span>
<span class="line"><span> ╰───────────────────────────────────────────────────────────────────────────────╯</span></span>
<span class="line"><span>   space ticks · ←→ picks · type into a field · enter runs · esc gives up</span></span></code></pre></div><p><strong>Every line has the same three columns</strong>: the flag on the left, the field in the middle, what it means on the right, faded. A thing spread over two lines is a thing you have to assemble before you can read it, and there is width to spare.</p><p>A field shows what you <strong>typed</strong> in bold, or what happens anyway in grey, with a cursor blinking in it — which is the only way of saying <em>type here</em> that nobody has to be taught. Chips are ticked with space, walked with <code>←→</code>, and clicked.</p><p><strong>Ticking two of anything is a <a href="./matrices">matrix</a>.</strong> Two environments, two values of a tag and two of a parameter are eight runs — for exactly the reason a comma is, and the window builds exactly that comma. Below the rule, in its own colour, is that command: not a prompt, and nobody is being asked to type it — it is what is about to happen, said once, so that the day you want it in a script you already know what to write.</p><h2 id="output-under-j-over-ssh-and-from-yesterday" tabindex="-1">Output under -j, over ssh, and from yesterday <a class="header-anchor" href="#output-under-j-over-ssh-and-from-yesterday" aria-label="Permalink to &quot;Output under -j, over ssh, and from yesterday&quot;">​</a></h2><p><strong>Each case&#39;s output is read from the file that case is writing</strong>, never from a share of one pipe. The paths are worked out before the run starts, so the name is known in advance — which is why it reads the same under <code>-j 8</code>, for a run on another machine, and for a job submitted yesterday.</p><p>Tick <code>detach</code>, close the window, open it tomorrow: the state was never in the screen. A run started <em>from</em> the screen belongs to the screen, so leaving is refused while one is going — <a href="./detached"><code>detach</code></a> is how work is meant to outlive a window.</p><h2 id="all-the-keys" tabindex="-1">All the keys <a class="header-anchor" href="#all-the-keys" aria-label="Permalink to &quot;All the keys&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><code>F1</code>…<code>F12</code></td><td>one per thing to do — see the table at the top</td></tr><tr><td><code>tab</code></td><td>the next rectangle of this page</td></tr><tr><td>typing</td><td>the search, on either page</td></tr><tr><td>arrows, click, wheel</td><td>move · choose and activate · scroll what is under the pointer</td></tr><tr><td>space</td><td>tick a case, or fold — <code>ctrl-space</code> while a search is on</td></tr><tr><td>enter</td><td>cases: ask where · runs: its files · files: open it</td></tr><tr><td><code>esc</code></td><td>clear the search, then leave</td></tr><tr><td><code>F9</code>, <code>F1</code>, <code>F12</code></td><td>read the project again · the keys · leave</td></tr></tbody></table><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><p><a href="./configuration">Configuration</a>.</p>`,32))])}const m=s(d,[["render",h]]);export{y as __pageData,m as default};
